/**
 * Shared discovery state: the loader options, the per-project context every loader receives, and the diagnostic helpers.
 */
import { relative } from "node:path";
import { pathToFileURL } from "node:url";
import { toPosix } from "./fs.js";
import { isRecord } from "../is-record.js";
export async function defaultImportModule(absolutePath) {
    const loaded = await import(pathToFileURL(absolutePath).href);
    if (!isRecord(loaded)) {
        throw new Error(`module is not an object: ${absolutePath}`);
    }
    return loaded;
}
/**
 * Classify a throw from `defaultImportModule`.
 * `ERR_MODULE_NOT_FOUND` and `MODULE_NOT_FOUND` come from `error.code`.
 * The missing specifier is only in the message. Ignore relative and absolute paths.
 */
export function moduleLoadFailure(error) {
    const code = thrownCode(error);
    if (code !== "ERR_MODULE_NOT_FOUND" && code !== "MODULE_NOT_FOUND") {
        return { code: "module_load_failed" };
    }
    const packageName = missingNpmPackage(errorMessage(error));
    if (packageName === undefined) {
        return { code: "module_not_found" };
    }
    return { code: "module_not_found", package: packageName };
}
export function missingNpmPackage(message) {
    const namedPackage = /Cannot find package '([^'\n]+)'/.exec(message)?.[1];
    if (namedPackage !== undefined) {
        return barePackageName(namedPackage);
    }
    const specifier = /Cannot find module '([^'\n]+)'/.exec(message)?.[1];
    if (specifier === undefined) {
        return undefined;
    }
    return barePackageName(specifier);
}
function barePackageName(specifier) {
    if (specifier.startsWith("./") ||
        specifier.startsWith("../") ||
        specifier.startsWith("/") ||
        specifier.startsWith("\\\\") ||
        specifier.startsWith("node:") ||
        specifier.includes("://") ||
        /^[A-Za-z]:[\\/]/.test(specifier)) {
        return undefined;
    }
    const scoped = /^(@[^/]+\/[^/]+)(?:\/.*)?$/.exec(specifier);
    if (scoped?.[1] !== undefined) {
        return scoped[1];
    }
    const name = /^([^/]+)/.exec(specifier)?.[1];
    if (name === undefined || name === "" || name.startsWith(".")) {
        return undefined;
    }
    return name;
}
function thrownCode(error) {
    if (typeof error !== "object" || error === null || !("code" in error)) {
        return undefined;
    }
    return typeof error.code === "string" ? error.code : undefined;
}
export function pushModuleLoadDiagnostic(ctx, modulePath, error) {
    const failure = moduleLoadFailure(error);
    ctx.diagnostics.push({
        severity: "error",
        code: failure.code,
        path: displayPath(ctx, modulePath),
        package: failure.package,
        message: `Failed to load module: ${errorMessage(error)}`,
    });
}
export function pushConfigDiagnostic(ctx, diagnostic) {
    ctx.diagnostics.push({ ...diagnostic, code: "config_error" });
}
export function displayPath(ctx, absolutePath) {
    return toPosix(relative(ctx.rootDir, absolutePath));
}
export function errorMessage(error) {
    return error instanceof Error ? error.message : String(error);
}
export function isBlank(value) {
    return typeof value !== "string" || value.trim() === "";
}
